effect.shader:
void main(){
    vec4 src = texture2DCv(inputImg.texture, acScreenNorm);
    float pos = fract(acTime*speed);
    float d = abs(acScreenNorm.y - pos);
    float band = smoothstep(width, 0.0, d);
    vec3 add = color.rgb * band * glow;
    vec3 base = src.rgb;
    vec3 outc = 1.0 - (1.0 - base) * (1.0 - add * src.a);
    gl_FragColor = vec4(outc, src.a) + vec4(add, band) * (1.0 - src.a);
}
